import{_ as a,o as e,c as i,a2 as d}from"./chunks/framework.GbRRgL9t.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md","lastUpdated":1789902237000}'),s={name:"getting-started/quickstart.md"};function o(l,t,n,r,c,h){return e(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>本页带你以最短路径在本机跑起 CircleChat。</p><h2 id="_1-环境要求" tabindex="-1">1. 环境要求 <a class="header-anchor" href="#_1-环境要求" aria-label="Permalink to &quot;1. 环境要求&quot;">​</a></h2><ul><li><strong>Node.js ≥ 22.5</strong>（使用内建 <code>node:sqlite</code>，过低版本启动即崩溃；<code>vite build</code> 需 Node ≥ 20.19）</li><li>npm（建议 ≥ 10，避免旧版 npm 改写 <code>package-lock.json</code>）</li></ul><h2 id="_2-安装依赖" tabindex="-1">2. 安装依赖 <a class="header-anchor" href="#_2-安装依赖" aria-label="Permalink to &quot;2. 安装依赖&quot;">​</a></h2><p>在项目根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>依赖仅用于<strong>构建期</strong>（前端打包 + 后端打包），服务运行时无第三方依赖。</p><h2 id="_3-构建" tabindex="-1">3. 构建 <a class="header-anchor" href="#_3-构建" aria-label="Permalink to &quot;3. 构建&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><ul><li>前端经 Vite 构建到 <code>public/dist/</code></li><li>后端经 Nitro 构建到 <code>.output/</code>（产物入口 <code>.output/server/index.mjs</code>）</li></ul><h2 id="_4-启动" tabindex="-1">4. 启动 <a class="header-anchor" href="#_4-启动" aria-label="Permalink to &quot;4. 启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>默认监听 <code>0.0.0.0:8090</code>。浏览器访问 <code>http://localhost:8090</code>，根路径 <code>/</code> 自动跳转登录页。</p><h2 id="_5-首次登录" tabindex="-1">5. 首次登录 <a class="header-anchor" href="#_5-首次登录" aria-label="Permalink to &quot;5. 首次登录&quot;">​</a></h2><p>首次启动若用户表为空，会自动创建管理员：</p><ul><li>用户名：<code>admin</code></li><li>密码：<code>Admin1234</code></li></ul><p><strong>生产部署后请尽快修改默认密码。</strong></p><h2 id="常用命令一览" tabindex="-1">常用命令一览 <a class="header-anchor" href="#常用命令一览" aria-label="Permalink to &quot;常用命令一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>npm install</code></td><td>安装依赖（首次，或依赖变更后）</td></tr><tr><td><code>npm run build</code></td><td>构建前端（Vite）与后端（Nitro）</td></tr><tr><td><code>npm start</code></td><td>启动生产服务（默认 <code>0.0.0.0:8090</code>）</td></tr><tr><td><code>npm run dev</code></td><td>开发模式：监听 <code>src/</code> 增量构建 + 启动 Nitro dev，改代码即时生效</td></tr><tr><td><code>npm run typecheck</code></td><td>类型检查（前端 <code>vue-tsc</code> + 后端 <code>tsc</code>，与 CI 一致）</td></tr><tr><td><code>npm run adduser -- &lt;用户名&gt; [新密码]</code></td><td>用户管理：新增用户或重置密码</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>查看<a href="./installation.html">生产部署</a>以接入 Nginx / 反向代理 / 容器。</li><li>查看<a href="./configuration.html">配置说明</a>了解端口、上传保留与地址分离。</li></ul>',22)])])}const k=a(s,[["render",o]]);export{u as __pageData,k as default};
